 static T Finish<T>(Task<T> task){var until=DateTime.UtcNow.AddSeconds(20);while(!task.IsCompleted&&DateTime.UtcNow<until){Application.DoEvents();System.Threading.Thread.Sleep(10);}Need(task.IsCompleted,"Fixture timed out");return task.GetAwaiter().GetResult();}
 static void TransactionTests(string root,string active){var flags=BindingFlags.Instance|BindingFlags.NonPublic;var form=(Launcher)Activator.CreateInstance(typeof(Launcher),true);try{string legacy=Path.Combine(root,"content","starter");Directory.CreateDirectory(legacy);File.WriteAllText(Path.Combine(legacy,"index.json"),"{\"old\":true}");var pack=new Dictionary<string,object>{{"id","starter"},{"files",new Dictionary<string,object>()},{"index",new Dictionary<string,object>{{"revision",1}}}};var install=typeof(Launcher).GetMethod("InstallContent",flags);string first=Finish((Task<string>)install.Invoke(form,new object[]{pack,legacy}));pack["index"]=new Dictionary<string,object>{{"revision",2}};string second=Finish((Task<string>)install.Invoke(form,new object[]{pack,first}));Need(first!=second&&File.Exists(Path.Combine(first,"index.json"))&&File.Exists(Path.Combine(legacy,"index.json")),"Failed transaction would overwrite old content");var json=new System.Web.Script.Serialization.JavaScriptSerializer();File.WriteAllText(Path.Combine(root,"state.json.previous"),json.Serialize(new Dictionary<string,object>{{"client",active},{"assets",new Dictionary<string,object>{{"starter",legacy}}}}));File.WriteAllText(Path.Combine(root,"state.json"),json.Serialize(new Dictionary<string,object>{{"client",active},{"assets",new Dictionary<string,object>{{"starter",second}}}}));Static("CleanupOwned",false);Need(Directory.Exists(second)&&!Directory.Exists(first)&&!Directory.Exists(legacy),"Committed content cleanup or rollback retention failed");
 string transport=Path.Combine(root,"transport"),previous=Path.Combine(root,"repair-source");Directory.CreateDirectory(transport);Directory.CreateDirectory(previous);File.WriteAllText(Path.Combine(transport,"TerrainFoundry.exe"),"correct");File.WriteAllText(Path.Combine(previous,"TerrainFoundry.exe"),"corrupt");Environment.SetEnvironmentVariable("TERRAIN_TEST_RELEASE",transport);string expected=(string)Static("Hash",Path.Combine(transport,"TerrainFoundry.exe"));var descriptor=new Dictionary<string,object>{{"sha256",expected},{"size",7},{"url","https://github.com/MGN-Consultancy/TerrainFoundry/releases/download/fixture/TerrainFoundry.exe"}};var component=new Dictionary<string,object>{{"files",new Dictionary<string,object>{{"TerrainFoundry.exe",descriptor}}}};string repaired=Path.Combine(root,"repair-target");Finish((Task<string>)typeof(Launcher).GetMethod("InstallFileSet",flags).Invoke(form,new object[]{component,repaired,previous,false}));Need(File.ReadAllText(Path.Combine(repaired,"TerrainFoundry.exe"))=="correct","Corrupt repair bytes reused");File.WriteAllText(Path.Combine(repaired,"extra.dll"),"unexpected");try{Static("CheckClient",repaired,component);throw new Exception("Unexpected file accepted");}catch(TargetInvocationException e){Need(e.InnerException.Message.Contains("Unexpected"),"Wrong strict client verification failure");}Console.WriteLine("PASS immutable content preserves failed-transaction baseline, commit cleans rollback, corrupt repair downloads verified replacement, unexpected editor files rejected.");}finally{form.Dispose();}}
 static void RetryCleanupTests(string root,string active){var form=(Launcher)Activator.CreateInstance(typeof(Launcher),true);string old=Path.Combine(root,"packages",new string('c',64));Directory.CreateDirectory(old);File.WriteAllText(Path.Combine(old,"verified.json"),"{}");string executable=Path.Combine(active,"TerrainFoundry.exe"),correct=File.ReadAllText(executable),hash=(string)Static("Hash",executable);var release=new Dictionary<string,object>{{"schema",2},{"client",new Dictionary<string,object>{{"files",new Dictionary<string,object>{{"TerrainFoundry.exe",new Dictionary<string,object>{{"sha256",hash}}}}}}},{"assets",new object[0]}};var method=typeof(Launcher).GetMethod("ValidateAndCleanup",BindingFlags.Instance|BindingFlags.NonPublic);try{foreach(bool missing in new[]{false,true}){if(missing)File.Delete(executable);else File.WriteAllText(executable,"corrupt");var task=(Task)method.Invoke(form,new object[]{active,release,new Dictionary<string,object>()});var until=DateTime.UtcNow.AddSeconds(10);while(!task.IsCompleted&&DateTime.UtcNow<until){Application.DoEvents();System.Threading.Thread.Sleep(10);}try{task.GetAwaiter().GetResult();throw new Exception("Invalid active installation accepted");}catch(Exception e){Need(e.Message.Contains("Editor files"),"Wrong invalid-client rejection");}Need(Directory.Exists(old),"Invalid current client lost rollback");}File.WriteAllText(executable,correct);var valid=(Task)method.Invoke(form,new object[]{active,release,new Dictionary<string,object>()});var deadline=DateTime.UtcNow.AddSeconds(10);while(!valid.IsCompleted&&DateTime.UtcNow<deadline){Application.DoEvents();System.Threading.Thread.Sleep(10);}valid.GetAwaiter().GetResult();Need(!Directory.Exists(old)&&File.Exists(executable),"Deferred cleanup did not retry after valid offline launch checks");Console.WriteLine("PASS later offline launch retries cleanup after validation; missing/corrupt active editor preserves rollback.");}finally{File.WriteAllText(executable,correct);form.Dispose();}}
 static void LinkTest(string root,string outside){string link=Path.Combine(root,"linked-fixture");var start=new ProcessStartInfo(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.System),"WindowsPowerShell","v1.0","powershell.exe")){UseShellExecute=false,CreateNoWindow=true,Arguments="-NoProfile -NonInteractive -Command \"$null=New-Item -ItemType Junction -Path '"+link.Replace("'","''")+"' -Target '"+outside.Replace("'","''")+"'\""};using(var process=Process.Start(start)){process.WaitForExit();Need(process.ExitCode==0,"Could not create junction safety fixture");}try{try{Static("DeleteOwned",link);throw new Exception("Linked cleanup accepted");}catch(TargetInvocationException e){Need(e.InnerException.Message.Contains("linked"),"Wrong linked-path refusal");}Need(File.Exists(Path.Combine(outside,"preserve.txt")),"Linked target changed");}finally{Directory.Delete(link);}}
 static void CleanupTests(string root){string marker=Path.Combine(root,"installation.json"),packages=Path.Combine(root,"packages"),active=Path.Combine(packages,"client-"+new string('a',64)),old=Path.Combine(packages,new string('b',64)),unknown=Path.Combine(packages,"my-projects"),outside=Path.Combine(Path.GetDirectoryName(root),"terrain-outside-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(active);Directory.CreateDirectory(old);Directory.CreateDirectory(unknown);Directory.CreateDirectory(outside);File.WriteAllText(Path.Combine(active,"TerrainFoundry.exe"),"active");File.WriteAllText(Path.Combine(old,"verified.json"),"{}");File.WriteAllText(Path.Combine(unknown,"my-file.txt"),"preserve");File.WriteAllText(Path.Combine(root,"personal.txt"),"preserve");File.WriteAllText(Path.Combine(outside,"preserve.txt"),"preserve");var json=new System.Web.Script.Serialization.JavaScriptSerializer();File.WriteAllText(Path.Combine(root,"state.json"),json.Serialize(new Dictionary<string,object>{{"client",active},{"assets",new Dictionary<string,object>()}}));try{try{Static("CleanupOwned",false);throw new Exception("Missing marker accepted");}catch(TargetInvocationException e){Need(e.InnerException.Message.Contains("marker"),"Wrong missing-marker failure");}Need(Directory.Exists(old),"Unmanaged cleanup removed files");File.WriteAllText(marker,"{ \"managedInstall\": true }");try{Static("SafeOwnedPath",outside);throw new Exception("Outside path accepted");}catch(TargetInvocationException e){Need(e.InnerException.Message.Contains("outside"),"Wrong outside-root failure");}LinkTest(root,outside);TransactionTests(root,active);RetryCleanupTests(root,active);Static("CleanupOwned",false);Need(Directory.Exists(active)&&!Directory.Exists(old),"Version cleanup failed");Need(File.Exists(Path.Combine(unknown,"my-file.txt"))&&File.Exists(Path.Combine(root,"personal.txt")),"Unrelated files removed");Static("CleanupOwned",true);Need(!Directory.Exists(active)&&!File.Exists(Path.Combine(root,"state.json")),"Uninstall payload retained");Need(File.Exists(Path.Combine(unknown,"my-file.txt"))&&File.Exists(Path.Combine(outside,"preserve.txt"))&&File.Exists(marker),"Uninstall removed preserved data or MSI marker");Console.WriteLine("PASS marker required, outside-root refused, obsolete version removed, current version retained, uninstall preserves unrelated data and MSI files.");}finally{Directory.Delete(outside,true);}}
 [STAThread]static void Main(){Application.EnableVisualStyles();if(Path.GetFileName(Application.ExecutablePath)=="TerrainFoundry.exe"){var target=Environment.GetEnvironmentVariable("TERRAIN_ASSET_PACKS");if(String.IsNullOrEmpty(target))throw new Exception("Scenery environment missing");var child=new Form{Text="Isolated editor startup fixture"};child.Shown+=(s,e)=>File.WriteAllText(Environment.GetEnvironmentVariable("TERRAIN_UI_RECEIPT"),Process.GetCurrentProcess().Id+"\n"+target);Application.Run(child);return;}string root=Path.Combine(Path.GetTempPath(),"terrain-launcher-ui-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);Environment.SetEnvironmentVariable("TERRAIN_TEST_ROOT",root);var flags=BindingFlags.Instance|BindingFlags.NonPublic;var method=typeof(Launcher).GetMethod("OpenVerifiedEditor",flags);int childPid=0;try{CleanupTests(root);var form=(Form)Activator.CreateInstance(typeof(Launcher),true);form.Show();Application.DoEvents();var status=(Label)typeof(Launcher).GetField("status",flags).GetValue(form);if(status.Bounds.Bottom>form.ClientSize.Height)throw new Exception("Status clipped");typeof(Launcher).GetField("batchTotal",flags).SetValue(form,3000000000L);typeof(Launcher).GetField("batchComplete",flags).SetValue(form,1000000000L);typeof(Launcher).GetField("batchCurrent",flags).SetValue(form,500000000L);typeof(Launcher).GetField("batchCount",flags).SetValue(form,3);typeof(Launcher).GetField("batchDone",flags).SetValue(form,1);typeof(Launcher).GetMethod("Progress",flags).Invoke(form,new object[]{"Downloading fixture",50});if(!status.Text.Contains("Overall 50%")||!status.Text.Contains("1 of 3 packages ready")||!status.Text.Contains("1.50 GB"))throw new Exception("Overall download progress missing");typeof(Launcher).GetField("batchCurrent",flags).SetValue(form,2000000000L);typeof(Launcher).GetMethod("Progress",flags).Invoke(form,new object[]{"Verifying fixture",-1});if(!status.Text.Contains("Overall 99%"))throw new Exception("Unverified download reported complete");typeof(Launcher).GetField("batchTotal",flags).SetValue(form,0L);var play=(Button)typeof(Launcher).GetField("play",flags).GetValue(form);if(play.Right>form.ClientSize.Width||play.Bottom>play.Parent.ClientSize.Height)throw new Exception("Open Editor clipped");var fail=(Task)method.Invoke(form,new object[]{Path.Combine(root,"missing"),new Dictionary<string,object>()});try{fail.GetAwaiter().GetResult();throw new Exception("Missing editor accepted");}catch(System.ComponentModel.Win32Exception){}if(form.IsDisposed)throw new Exception("Failed launch closed launcher");string client=Path.Combine(root,"client");Directory.CreateDirectory(client);File.Copy(Application.ExecutablePath,Path.Combine(client,"TerrainFoundry.exe"));string receipt=Path.Combine(root,"child.txt");Environment.SetEnvironmentVariable("TERRAIN_UI_RECEIPT",receipt);var task=(Task)method.Invoke(form,new object[]{client,new Dictionary<string,object>{{"fixture",root}}});var timeout=DateTime.UtcNow.AddSeconds(15);while(!task.IsCompleted&&DateTime.UtcNow<timeout){Application.DoEvents();System.Threading.Thread.Sleep(10);}task.GetAwaiter().GetResult();if(!form.IsDisposed)throw new Exception("Successful launch left launcher open");timeout=DateTime.UtcNow.AddSeconds(5);string[] lines=null;while(DateTime.UtcNow<timeout){try{if(File.Exists(receipt)){var candidate=File.ReadAllLines(receipt);if(candidate.Length>=2){lines=candidate;break;}}}catch(IOException){}System.Threading.Thread.Sleep(25);}if(lines==null)throw new Exception("Editor startup receipt was not written completely");childPid=Int32.Parse(lines[0]);Need((bool)Static("EditorRunning"),"Running editor not detected");try{Static("CleanupOwned",true);throw new Exception("Running-editor uninstall accepted");}catch(TargetInvocationException e){Need(e.InnerException.Message.Contains("Close"),"Wrong running-editor refusal");}if(!lines[1].Contains("fixture"))throw new Exception("Scenery paths lost");Console.WriteLine("PASS launcher controls fit, failed startup remains open, successful editor startup closes launcher and passes scenery paths.");}finally{if(childPid!=0)using(var child=Process.GetProcessById(childPid)){if(child.MainModule.FileName==Path.Combine(root,"client","TerrainFoundry.exe")){child.Kill();child.WaitForExit(5000);}}Directory.Delete(root,true);}}}}
